#!/usr/bin/env python3

import argparse
import csv
import json
from decimal import Decimal, ROUND_HALF_UP
from datetime import datetime

def parse_timestamp(ts: str) -> datetime:
    """Parse an ISO8601 timestamp with optional UTC offset into a timezone‑aware datetime."""
    # datetime.fromisoformat handles offsets in the form ±HH:MM
    return datetime.fromisoformat(ts)

def main():
    parser = argparse.ArgumentParser(description='Reconcile payment transactions from a CSV file.')
    parser.add_argument('--input', required=True, help='Path to the input CSV file')
    args = parser.parse_args()

    records = {}
    with open(args.input, newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            tx_id = row['tx_id']
            # Parse timestamp and amount safely
            try:
                ts = parse_timestamp(row['timestamp'])
            except Exception as e:
                # Skip rows with unparsable timestamps
                continue
            try:
                amount = Decimal(row['amount'])
            except Exception:
                continue
            status = row['status']
            # Keep the most recent record for each tx_id
            if tx_id not in records or ts > records[tx_id][0]:
                records[tx_id] = (ts, amount, status)

    total_valid_amount = Decimal('0')
    valid_count = 0
    failed_count = 0
    for ts, amount, status in records.values():
        if status == 'VALID':
            total_valid_amount += amount
            valid_count += 1
        else:
            failed_count += 1

    # Round to two decimal places
    total_valid_amount = total_valid_amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    result = {
        "total_valid_amount": str(total_valid_amount),
        "valid_count": valid_count,
        "failed_count": failed_count
    }
    print(json.dumps(result))

if __name__ == '__main__':
    main()
